"use client";

import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "../../lib/utils";
import { ChevronDown } from "./icons";

// Accordion: generated by UIX from the design system. Same variants and sizes as the Figma component.

const accordionVariants = cva(
  "skin-quiet group/accordion w-full rounded-lg",
  {
    variants: {
      appearance: {
        default: "border border-0 border-b border-line-subtle",
        bordered: "px-4 py-1 border border-line-default",
        filled: "px-4 py-1 bg-subtle",
      },
    },
    compoundVariants: [
      { appearance: "default", class: "rounded-none" },
    ],
    defaultVariants: {
      appearance: "default",
    },
  },
);

export interface AccordionItemProps
  extends Omit<React.DetailsHTMLAttributes<HTMLDetailsElement>, "title">,
    VariantProps<typeof accordionVariants> {
  title: React.ReactNode;
}

const AccordionItem = React.forwardRef<HTMLDetailsElement, AccordionItemProps>(
  ({ className, appearance, title, children, ...props }, ref) => (
    <details data-slot="accordion" data-kind="surface" ref={ref} className={cn(accordionVariants({ appearance }), className)} {...props}>
      <summary className="flex cursor-pointer list-none items-center justify-between gap-3 py-[14px] text-label-large text-fg-primary rounded-xs [&::-webkit-details-marker]:hidden focus-visible:outline-none focus-visible:ring-3 focus-visible:ring-line-focus">
        {title}
        <ChevronDown aria-hidden className="size-5 shrink-0 transition-transform group-open/accordion:rotate-180 text-icon-secondary" />
      </summary>
      <div className="pb-4 text-body-medium text-fg-secondary">{children}</div>
    </details>
  ),
);
AccordionItem.displayName = "AccordionItem";

const Accordion = React.forwardRef<HTMLDivElement, React.HTMLAttributes<HTMLDivElement>>(({ className, ...props }, ref) => (
  <div ref={ref} className={cn("w-full", className)} {...props} />
));
Accordion.displayName = "Accordion";

export { Accordion, AccordionItem, accordionVariants };
